      stallAfterMs: 170,
      recoveryAfterMs: 100,
      floor: 0.07,
      // Peak openness of the procedural fallback (small).
      amplitude: 0.07,
      // Oscillation speed of the fallback mouth motion (rad/s).
      speed: 8
